W=[
E('reverberate','英 /rɪˈvɜːbəreɪt/；美 /rɪˈvɜːrbəreɪt/','回响；产生持续影响','声音撞上墙又回来；一件事过去了，影响还在四处传开。','拉丁 re- 回来 + verberare 击打 → reverberare 弹回、反射，英语接其分词词干 reverberat-。声音回荡义由反射展开。',[['拉丁 re- + verberare → reverberare／reverberatus','击打回来、反弹'],['英语 reverberate','声音回响；比喻事件影响持续传播']],'鼓声在大厅里 reverberate，是原声之后仍有回响。新闻的影响 reverberate through an industry，则是它一层层传到行业各处，事情结束后也未马上消失。比喻仍保留余波传开的感觉。','reverberate through a hall；reverberate around a room；reverberate across an industry。','echo 常让人想到可分辨的一声声重复；reverberate 更突出空间里持续回荡。抽象用法讲影响，不必真的有声音。',('The drumbeat reverberated through the empty hall.','鼓声在空荡的大厅里回荡。'),('The decision continued to reverberate across the industry.','这个决定的影响持续波及整个行业。'),sources=['https://www.etymonline.com/word/reverberate','https://en.wiktionary.org/wiki/reverberate#English']),
E('reverberation','英 /rɪˌvɜːbəˈreɪʃən/；美 /rɪˌvɜːrbəˈreɪʃən/','回响；混响；持续的反响','声音已经发完，房间里却还留着一段拖尾。','英语经法语 reverberacion 及中世纪拉丁 reverberatio 借入，关联拉丁 reverberare 击回。名词在英语中早于 reverberate，现代可联系 -ation，但历史不是英语动词直接新造。',[['拉丁 reverberare → 中世纪拉丁 reverberatio；法语 reverberacion','击回、反射 → 反射现象'],['英语 reverberation','反射、回响；声音混响及比喻的余波']],'空房间拍手后那段不马上消失的声音，是理解 reverberation 的好入口。它来自许多反射声叠在一起。复数 reverberations 常写事件留下的影响，例如政治决定持续引起讨论与变化。','reverberation in a room；reverberation time；the political reverberations of an event。','reverberation 不一定是一声清清楚楚的回声；很多反射密集叠加时，会形成连着的声音尾巴。普通语境可宽泛说回响，声学语境则更精确。',('Thick curtains reduced the reverberation in the room.','厚窗帘减轻了房间里的混响。'),('The political reverberations of the announcement lasted for months.','这项公告引发的政治反响持续了几个月。'),sources=['https://www.etymonline.com/word/reverberation','https://en.wiktionary.org/wiki/reverberation#English']),
E('reverb','名词：英 /ˈriːvɜːb/；美 /ˈriːvɜːrb/','混响；混响效果','给录音添上一点房间回声的尾巴，让声音有空间感。','现代音乐和音频用语中，reverb 是 reverberation 的截短形式。它不是 re- 再次加英语 verb 动词。',[['英语 reverberation → 截短 reverb','保留原词开头，形成简短音频术语'],['英语名词 reverb','混响及人工加入的混响效果']],'干的人声录音听起来很近、很直接；加一点 reverb，可以让它像在较大的空间中响起。过多时也可能让音节糊在一起。这里讲的是听觉空间和尾音，不是把歌唱得更响。','add reverb；a touch of reverb；too much reverb；a reverb effect。','volume 管响度；reverb 管声音的空间回响效果。它也与把整段声音原样重播的普通重复不同。',('Add a little reverb to make the vocal sound less dry.','加一点混响，让人声听起来不那么干。'),('Too much reverb made the spoken words hard to understand.','混响太多，反而让说话内容听不清了。'),sources=['https://dictionary.cambridge.org/us/dictionary/english/reverb','https://www.etymonline.com/word/reverberation','https://en.wiktionary.org/wiki/reverb#English'])]
ROOT=dict(id='C1621',meaning='击打；与 re- 结合表示反弹、反射',core='VERBER = STRIKE / BEAT',image='声音碰到四壁折回来，一层叠一层，留下回响。',intro='拉丁 verberare 是击打，reverberare 是击回、反弹。英语沿反射这一层发展出回响，又用声音的余波形容事件的长期影响。',forms='re- 回来 + verberare 击打 → reverberare；其分词词干接入 reverberate，名词 reverberatio 另经法语等成为 reverberation；reverb 是现代截短词。',branches=[['回响的动作','reverberate'],['回响现象与音频效果','reverberation；reverb']],contrasts='这些词的 verb 字母不是英语词性名词 verb 动词。reverberation 的历史早于英语动词，不应画成英语动词依次生出所有词。',practice='The hall’s reverberation made every drumbeat reverberate for longer.\n\n大厅的混响让每一记鼓声都回荡得更久。',words=[x['word'] for x in W],exclude={})
